  mem_inv bsegs m ->
  evt bsegs (fun ms' => exists m',
      ms' = MS (mkR (wz ABF_RA1) (wz (bv_unsigned sp + -16)) gp tp t0 t1 t2 (wz Fa) s1 (wz Fa) a1 a2 a3 a4 a5 a6 a7
