      /\ munch [(bv_unsigned sp + -16, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
      /\ stk bsegs m' lo (bv_unsigned sp + -16)
      /\ rw_cells bsegs m' (bv_unsigned sp + -16) [C8 s0; C8 ra])
